  { external_id: "r-1002", name: "", email: "not-an-email", company: "Gamma", amount: null },
] } }];

// Escape text so Telegram's HTML parse mode shows it literally
const h = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const s = $json;
const node = s.error_node || s.stage;

// Fall back to a link built from this execution when the record has none
const url = s.execution_url || ('https://YOUR-N8N-HOST/workflow/' + $workflow.id + '/executions/' + $execution.id);

// Headline, detail and next step depend on the stage
let head, body, next;
if (s.stage === 'quarantine') {
  head = '🚨 RDI · Record quarantined';
  body = 'Record ' + h(s.entity_id) + ' · ' + h(s.error_message);
  next = 'Fix the listed fields and re-send ' + h(s.entity_id);
} else if (s.stage === 'scheduled_scan') {
  head = '⚠️ RDI · Reconcile scan failed';
  body = h(node) + ' · ' + h(s.error_message);
  next = 'Re-run Scheduled Reconcile Trigger after ' + h(node) + ' recovers';
} else {
  head = '⚠️ RDI · Sync failed, record pending';
  body = h(s.entity_id) + ' · ' + h(node) + ' · ' + h(s.error_message);
  next = 'Re-send the batch once ' + h(node) + ' recovers; the record stays pending-sync';
}

const text = [head, body, next, '#rdi · run ' + h(s.correlation_id) + ' · ' + url].join('\n');

return { json: { ...$json, text } };

const rows = $input.all().map(i => i.json);
const by = (s) => rows.filter(r => r.stage === s).length;
const quarantined = by("quarantine");
const skipped_unchanged = by("unchanged_skip");
const suppressed = by("suppressed");
const synced = by("synced");
const failed_sync = rows.filter(r => r.status === "handled_failure").length;
const airtable_count = synced + skipped_unchanged + suppressed;
const hubspot_count = synced;
return [{ json: {
  template: "reliable-data-intake-sync",
  run_id: "rdi_run_" + $execution.id,
  scope: "per_run",
  source_count: rows.length,
  airtable_count,
  hubspot_count,
  quarantined,
  skipped_unchanged,
  suppressed,
  synced,
  failed_sync,
  in_sync: failed_sync === 0,
  timestamp: $now.toISO(),
  execution_url: "https://YOUR-N8N-HOST/workflow/" + $workflow.id + "/executions/" + $execution.id,
} }];

// Escape text so Telegram's HTML parse mode shows it literally
const h = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const r = $json;

// in_sync can arrive as a boolean or the string 'true'
const ok = r.in_sync === true || String(r.in_sync) === 'true';
const scan = r.scope === 'scheduled_scan';
const label = scan ? 'scheduled scan' : 'per run';
const url = r.execution_url || ('https://YOUR-N8N-HOST/workflow/' + $workflow.id + '/executions/' + $execution.id);

// Headline: OK, or what drifted
const head = ok
  ? ('📊 RDI · Reconcile OK (' + label + ')')
  : ('⚠️ RDI · Reconcile drift (' + label + ') · ' + (scan
      ? ('airtable ' + h(r.airtable_count) + ' ≠ hubspot ' + h(r.hubspot_count))
      : (h(r.failed_sync) + ' failed sync')));

// Next step
const next = ok
  ? 'No action needed'
  : (scan
      ? 'Compare Airtable vs HubSpot counts; re-send the missing records'
      : 'Re-send the batch once the connector recovers; failed records stay pending-sync');

const text = [
  head,
  'source ' + h(r.source_count) + ' · airtable ' + h(r.airtable_count) + ' · hubspot ' + h(r.hubspot_count),
  'quarantined ' + h(r.quarantined) + ' · skipped ' + h(r.skipped_unchanged) + ' · suppressed ' + h(r.suppressed) + ' · failed ' + h(r.failed_sync),
  next,
  '#rdi · run ' + h(r.run_id) + ' · ' + url,
].join('\n');

return { json: { ...$json, text } };

const airtable = $('Retrieve Records from Airtable').all().map(i => i.json).filter(r => r && (r.id || r.fields));
const hubspot = $('Retrieve Contacts from HubSpot').all().map(i => i.json).filter(r => r && (r.vid || r.id));
const airtable_count = airtable.length;
const hubspot_count = hubspot.length;
return [{ json: {
  template: "reliable-data-intake-sync",
  run_id: "rdi_run_" + $execution.id,
  scope: "scheduled_scan",
  source_count: airtable_count,
  airtable_count,
  hubspot_count,
  quarantined: 0,
  skipped_unchanged: 0,
  suppressed: 0,
  synced: 0,
  failed_sync: 0,
  in_sync: airtable_count === hubspot_count,
  timestamp: $now.toISO(),
  execution_url: "https://YOUR-N8N-HOST/workflow/" + $workflow.id + "/executions/" + $execution.id,
} }];
